insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aberta a audiência, será dada a palavra ao defensor para responder à acusação, após o que o Juiz receberá, ou não, a denúncia ou queixa; havendo recebimento, serão ouvidas a vítima e as testemunhas de acusação e defesa, interrogando-se a seguir o acusado, passando-se aos debates orais e à sentença. Todas as provas serão produzidas na audiência, podendo o juiz limitar ou excluir as excessivas, impertinentes ou protelatórias. Durante a audiência, todos devem respeitar a dignidade da vítima, sob pena de responsabilização civil, penal e administrativa, vedadas manifestações sobre circunstâncias alheias aos fatos e linguagem ou material que ofendam a dignidade da vítima ou de testemunhas. Será lavrado termo, assinado pelo juiz e pelas partes, e a sentença dispensará o relatório.', '["Defesa antes do recebimento da denúncia.","Oitiva da vítima, testemunhas e interrogatório do acusado ao final.","Debates orais e sentença na própria audiência.","Respeito à dignidade da vítima.","Sentença sem relatório."]'::jsonb, '["ATUALIZAÇÃO: §1º-A incluído pela Lei nº 14.245, de 2021 (dignidade da vítima nas audiências).","O interrogatório é o ÚLTIMO ato de instrução."]'::jsonb, 'O juiz impede o advogado de usar linguagem ofensiva contra a vítima.', '["Assertiva que inicia a audiência com o interrogatório do acusado erra: o interrogatório vem depois da prova."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-81'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Da decisão de rejeição da denúncia ou queixa e da sentença caberá apelação, que poderá ser julgada por turma composta de três juízes em exercício no primeiro grau, reunidos na sede do Juizado. A apelação será interposta no prazo de dez dias, contados da ciência da sentença, por petição escrita com razões e pedido. O recorrido será intimado para responder por escrito em dez dias. As partes poderão requerer a transcrição da gravação. As partes serão intimadas da data do julgamento pela imprensa. Se a sentença for confirmada pelos próprios fundamentos, a súmula do julgamento servirá de acórdão.', '["Apelação contra a rejeição da denúncia e contra a sentença.","Turma de três juízes de primeiro grau.","Prazo de dez dias.","Resposta em dez dias.","Súmula como acórdão."]'::jsonb, '["Apelação em DEZ dias (no processo penal comum seriam cinco).","Julgada por turma recursal."]'::jsonb, 'O Ministério Público apela da rejeição da denúncia em dez dias.', '["Assertiva que fixa em cinco dias o prazo da apelação no Juizado Criminal erra: são dez dias."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-82'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cabem embargos de declaração quando, em sentença ou acórdão, houver obscuridade, contradição ou omissão. Serão opostos por escrito ou oralmente, no prazo de cinco dias, contados da ciência da decisão, e interrompem o prazo para a interposição de recurso. Os erros materiais podem ser corrigidos de ofício.', '["Embargos por obscuridade, contradição ou omissão.","Escritos ou orais, em cinco dias.","Interrompem o prazo do recurso.","Erros materiais corrigíveis de ofício."]'::jsonb, '["ATUALIZAÇÃO: o §2º (interrupção do prazo) foi alterado por lei posterior.","Interrompem (não suspendem) o prazo."]'::jsonb, 'A parte embarga oralmente de uma omissão na sentença.', '["Assertiva que fixa em dois dias o prazo dos embargos erra: são cinco."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-83'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicada exclusivamente pena de multa, seu cumprimento far-se-á mediante pagamento na Secretaria do Juizado. Efetuado o pagamento, o Juiz declarará extinta a punibilidade, determinando que a condenação não fique constando dos registros criminais, exceto para fins de requisição judicial.', '["Multa paga na Secretaria.","Pagamento extingue a punibilidade.","Sem registro criminal, exceto requisição judicial."]'::jsonb, '["Pagamento extingue a punibilidade."]'::jsonb, 'O autor paga a multa na Secretaria e o processo é extinto.', '["Assertiva que mantém a condenação nos registros criminais após o pagamento erra."]'::jsonb, '[]'::jsonb, '["Art. 85"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'juizados' and u.unit_key = 'art-84'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

