insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Suspensão condicional do processo: nos crimes em que a pena mínima cominada for igual ou inferior a um ano, abrangidas ou não pela Lei, o Ministério Público, ao oferecer a denúncia, poderá propor a suspensão do processo, por dois a quatro anos, desde que o acusado não esteja sendo processado ou não tenha sido condenado por outro crime e presentes os demais requisitos do sursis. Aceita a proposta, o juiz, recebendo a denúncia, poderá suspender o processo, submetendo o acusado a período de prova com as condições de reparação do dano, proibição de frequentar certos lugares, proibição de ausentar-se da comarca e comparecimento mensal a juízo. O juiz poderá fixar outras condições. A suspensão será revogada se o beneficiário vier a ser processado por outro crime ou não reparar o dano sem motivo justificado.', '["Pena mínima igual ou inferior a um ano.","Suspensão por dois a quatro anos.","Acusado não processado nem condenado por outro crime.","Condições: reparar o dano, frequentar lugares, ausentar-se da comarca e comparecer mensalmente.","Revogação obrigatória se processado por outro crime ou sem reparar o dano."]'::jsonb, '["Critério: pena MÍNIMA de até um ano (diferente do menor potencial ofensivo, que olha a máxima).","Aplica-se a crimes de qualquer lei, e não só aos dos Juizados."]'::jsonb, 'O acusado de furto simples, primário, aceita a suspensão do processo por dois anos.', '["Assertiva que considera a pena máxima para o sursis processual erra: o critério é a pena mínima de até um ano."]'::jsonb, '[{"termo":"Sursis processual","significado":"Suspensão do processo mediante condições e período de prova."}]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
